// Parse document and detect file type
const input = $input.first().json;
const body = input.body || input;

// Get file info
const fileData = body.file || body.document || {};
const base64Content = fileData.content || fileData.data || body.content;
const fileName = fileData.name || fileData.filename || body.filename || 'document';
const mimeType = fileData.mimeType || fileData.type || body.mimeType || 'application/octet-stream';

// Detect file type from extension or mime
const extension = fileName.split('.').pop()?.toLowerCase() || '';
const typeMap = {
  'pdf': 'pdf',
  'png': 'image',
  'jpg': 'image',
  'jpeg': 'image',
  'tiff': 'image',
  'tif': 'image',
  'docx': 'docx',
  'doc': 'doc',
  'txt': 'text'
};

const fileType = typeMap[extension] || (mimeType.includes('pdf') ? 'pdf' : 
  mimeType.includes('image') ? 'image' : 'unknown');

const document = {
  id: `doc_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  fileName,
  mimeType,
  fileType,
  hasContent: !!base64Content,
  contentLength: base64Content?.length || 0,
  schema: body.schema || body.extractionSchema || null,
  metadata: body.metadata || {},
  createdAt: new Date().toISOString()
};

return [{ json: document }];

