// Parse and validate extracted fields
const doc = $('Merge Extraction').first().json;
const aiResponse = $input.first().json;

let extractedFields;
try {
  const content = aiResponse.message?.content || aiResponse.choices?.[0]?.message?.content || '{}';
  extractedFields = JSON.parse(content);
} catch (e) {
  extractedFields = { error: 'Failed to parse AI response', raw: aiResponse };
}

// Validate against schema if provided
const validationErrors = [];
if (doc.schema && doc.schema.required) {
  for (const field of doc.schema.required) {
    if (!extractedFields[field]) {
      validationErrors.push(`Missing required field: ${field}`);
    }
  }
}

return [{
  json: {
    ...doc,
    extractedFields,
    validation: {
      valid: validationErrors.length === 0,
      errors: validationErrors
    }
  }
}];

// Store and archive valid document
const doc = $input.first().json;
const staticData = $workflow.staticData;

// Initialize document store
if (!staticData.documents) {
  staticData.documents = {};
}
if (!staticData.documentVersions) {
  staticData.documentVersions = {};
}

// Version management
const docKey = doc.fileName.replace(/\.[^.]+$/, '');
if (!staticData.documentVersions[docKey]) {
  staticData.documentVersions[docKey] = [];
}
staticData.documentVersions[docKey].push({
  version: staticData.documentVersions[docKey].length + 1,
  documentId: doc.id,
  archivedAt: new Date().toISOString()
});

// Store document
staticData.documents[doc.id] = {
  id: doc.id,
  fileName: doc.fileName,
  fileType: doc.fileType,
  extractedFields: doc.extractedFields,
  version: staticData.documentVersions[docKey].length,
  archivedAt: new Date().toISOString(),
  retentionPolicy: '7years'
};

return [{
  json: {
    ...doc,
    archived: true,
    version: staticData.documentVersions[docKey].length,
    archiveId: `arc_${doc.id}`
  }
}];

// Flag for manual review
const doc = $input.first().json;
const staticData = $workflow.staticData;

// Initialize review queue
if (!staticData.reviewQueue) {
  staticData.reviewQueue = [];
}

staticData.reviewQueue.push({
  documentId: doc.id,
  fileName: doc.fileName,
  validationErrors: doc.validation.errors,
  extractedFields: doc.extractedFields,
  addedAt: new Date().toISOString()
});

return [{
  json: {
    ...doc,
    flaggedForReview: true,
    reviewReason: doc.validation.errors.join(', '),
    queuePosition: staticData.reviewQueue.length
  }
}];

// Format final response
const doc = $input.first().json;

const response = {
  success: !doc.error,
  documentId: doc.id,
  fileName: doc.fileName,
  fileType: doc.fileType,
  processing: {
    method: doc.processingMethod,
    ocrUsed: doc.ocrRequired || false,
    ocrConfidence: doc.ocrConfidence || null
  },
  extraction: {
    fields: doc.extractedFields,
    validation: doc.validation
  },
  status: doc.archived ? 'archived' : 
          doc.flaggedForReview ? 'pending_review' : 
          doc.error ? 'failed' : 'processed',
  archive: doc.archived ? {
    archiveId: doc.archiveId,
    version: doc.version
  } : null,
  review: doc.flaggedForReview ? {
    reason: doc.reviewReason,
    queuePosition: doc.queuePosition
  } : null,
  processedAt: new Date().toISOString()
};

return [{ json: response }];
